export function WidgetFooter({
  note = "{{note}}",
  actionLabel = "{{actionLabel}}",
  showAction = {{showAction}},
  color = "{{color}}",
}) {
  return (
    <footer style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, font: "12px system-ui, sans-serif", color: "#241430", borderTop: "1px solid #24143018", paddingTop: 8, marginTop: 8 }}>
      <span style={{ opacity: 0.65 }}>{note}</span>
      {showAction && (
        <button type="button" style={{ background: "transparent", border: "1.5px solid " + color, borderRadius: 8, padding: "5px 10px", fontSize: 12, fontWeight: 600, cursor: "pointer", color: "#241430" }}>
          {actionLabel}
        </button>
      )}
    </footer>
  );
}
